"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([[79707],{22463:(e,t,o)=>{o.r(t),o.d(t,{assets:()=>r,contentTitle:()=>a,default:()=>d,frontMatter:()=>c,metadata:()=>n,toc:()=>l});const n=JSON.parse('{"id":"qiangguo/moderneconomics","title":"","description":"In an age overrun by sea turtles and lapdogs, Western modern economics is treated as theology. Theology is not to be discussed, much less deconstructed. Mythology does not exist -- even mathematics cannot serve as theology. Yet Western modern economics, which merely borrowed some axiomatic thinking from mathematics to swindle people, has been elevated to the status of theology. This in itself constitutes a new myth of China at the turn of the century.","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/qiangguo/moderneconomics.md","sourceDirName":"qiangguo","slug":"/qiangguo/moderneconomics","permalink":"/qiangguo/moderneconomics","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"moderneconomics","title":"","hide_table_of_contents":true},"sidebar":"qiangguoSidebar","previous":{"title":"\u6709\u610f\u65e0\u610f\u5730\u6df7\u6dc6\u897f\u65b9\u6587\u660e\u7684\u6982\u5ff5\uff0c\u5236\u9020\u4e1c\u897f\u65b9\u9694\u9602\uff0c\u96be\u9053\u5c31\u662f\u5de6\u6d3e\u7684\u4e00\u8d2f\u4f0e\u4fe9\uff1f","permalink":"/qiangguo/westcivilization"},"next":{"title":"\u7ad9\u5728\u6587\u5316\u4f20\u64ad\u3001\u7ee7\u627f\u7684\u89d2\u5ea6\uff0c\u4e2d\u56fd\u4eba\u5fc5\u987b\u5411\u65e5\u672c\u4eba\u5b66\u4e60\u3002","permalink":"/qiangguo/learnfromjapanese"}}');var s=o(74848),i=o(28453);const c={id:"moderneconomics",title:"",hide_table_of_contents:!0},a="Western Modern Economics Must Be Thoroughly Deconstructed -- Economics Is Essentially Nothing But Political Science Plus Psychology (2004-9-14)",r={},l=[];function h(e){const t={h1:"h1",header:"header",p:"p",...(0,i.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.header,{children:(0,s.jsx)(t.h1,{id:"western-modern-economics-must-be-thoroughly-deconstructed----economics-is-essentially-nothing-but-political-science-plus-psychology-2004-9-14",children:"Western Modern Economics Must Be Thoroughly Deconstructed -- Economics Is Essentially Nothing But Political Science Plus Psychology (2004-9-14)"})}),"\n",(0,s.jsx)(t.p,{children:"In an age overrun by sea turtles and lapdogs, Western modern economics is treated as theology. Theology is not to be discussed, much less deconstructed. Mythology does not exist -- even mathematics cannot serve as theology. Yet Western modern economics, which merely borrowed some axiomatic thinking from mathematics to swindle people, has been elevated to the status of theology. This in itself constitutes a new myth of China at the turn of the century."}),"\n",(0,s.jsx)(t.p,{children:"Those who enjoy preaching are really only of two kinds: those who are truly intoxicated, which is a psychological matter; and those who are truly clear-headed, which is a matter of interest. When it comes to interest, people are never stupid -- and interest is politics. Economics is the same: economics is political science at the level of interest, and psychology at the level of operation."}),"\n",(0,s.jsx)(t.p,{children:"At the level of interest, economics has always been political science. For any specific economic phenomenon, there is certainly more than one theoretical solution. But which one to choose is a political question. And the choice is what is most fundamental -- until that final decision is made, everything else is just noise. For example, regarding the current so-called inflation problem, there are many theoretical approaches. Which one to select is ultimately determined by political stance. So-called political stance, at its root, is a matter of the game between different interests. The political and interest-based motivations behind different methods are absolutely different."}),"\n",(0,s.jsx)(t.p,{children:"As for concrete operations, the effects of economic policy are transmitted more at the psychological level -- this involves questions of psychology. Economic phenomena are fundamentally the materialized process of psychological images. This can be clearly seen from market trading charts."}),"\n",(0,s.jsx)(t.p,{children:"Intentionally or unintentionally ignoring the above two points amounts to playing word games or number games. Swindling money in the study or at a private gathering is fine, but if the country relies on such people, it is truly in peril!"})]})}function d(e={}){const{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(h,{...e})}):h(e)}},28453:(e,t,o)=>{o.d(t,{R:()=>c,x:()=>a});var n=o(96540);const s={},i=n.createContext(s);function c(e){const t=n.useContext(i);return n.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function a(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:c(e.components),n.createElement(i.Provider,{value:t},e.children)}}}]);